// Only commands listed here get an autogenerated `allow-*`/`deny-*`
// permission. The credential vault is deliberately absent: it is a Rust-only
// API, so the webview can never reach it (unlisted plugin commands fail the
// ACL check before Tauri forwards them to the native plugin).
const COMMANDS: &[&str] = &["share_file"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .ios_path("ios")
        .build();
}
